let find =
  let tbl =
    lazy
      (let tbl = Hashtbl.create (Array.length table) in
       Array.iter (fun (name, t) -> Hashtbl.replace tbl name t) table;
       tbl)
  in
  fun name -> Hashtbl.find_opt (Lazy.force tbl) name
